typedef long long ll;

// Fast input
inline ll readLong() {
    ll num = 0;
    int c = getchar();
    bool neg = false;
    while (c != '-' && (c < '0' || c > '9')) c = getchar();
    if (c == '-') { neg = true; c = getchar(); }
    while (c >= '0' && c <= '9') {
